package projects

import (
	"fmt"
	"path/filepath"
	"regexp"
	"strings"
)

// Template describes a project preset exposed by the Hilt creation workflow.
// The preset delegates compilation and project-file generation to dotnet new.
type Template struct {
	ID          string
	Name        string
	Description string
	Projects    []TemplateProject
}

// TemplateProject is one project generated by a solution preset.
type TemplateProject struct {
	Name   string
	Folder string
	Kind   string
}

// CreateRequest describes a project or solution creation request.
type CreateRequest struct {
	TemplateID       string
	Name             string
	Destination      string
	ExistingSolution string
	CreateSolution   bool
}

// CreateStep is a dry-run operation shown before files are modified.
type CreateStep struct {
	Command []string
	Dir     string
}

// CreatePlan is a validated, deterministic creation plan.
type CreatePlan struct {
	Template Template
	Root     string
	Solution string
	Projects []string
	Steps    []CreateStep
}

var validTemplateName = regexp.MustCompile(`^[A-Za-z0-9][A-Za-z0-9._-]*$`)

var templateCatalog = []Template{
	{ID: "console", Name: "Console app", Description: "A command-line executable.", Projects: []TemplateProject{{Kind: "console"}}},
	{ID: "classlib", Name: "Class library", Description: "A reusable .NET class library.", Projects: []TemplateProject{{Kind: "classlib"}}},
	{ID: "webapi", Name: "ASP.NET Core Web API", Description: "An HTTP API with the modern ASP.NET Core defaults.", Projects: []TemplateProject{{Kind: "webapi"}}},
	{ID: "xunit", Name: "xUnit test project", Description: "A test project ready for xUnit.", Projects: []TemplateProject{{Kind: "xunit"}}},
	{ID: "clean-architecture", Name: "Clean Architecture", Description: "API, application, domain, infrastructure, and tests.", Projects: []TemplateProject{
		{Name: ".Api", Folder: "src", Kind: "webapi"},
		{Name: ".Application", Folder: "src", Kind: "classlib"},
		{Name: ".Domain", Folder: "src", Kind: "classlib"},
		{Name: ".Infrastructure", Folder: "src", Kind: "classlib"},
		{Name: ".Tests", Folder: "tests", Kind: "xunit"},
	}},
	{ID: "vertical-slice", Name: "Vertical Slice", Description: "A feature-oriented API with an accompanying test project.", Projects: []TemplateProject{
		{Name: ".Api", Folder: "src", Kind: "webapi"},
		{Name: ".Tests", Folder: "tests", Kind: "xunit"},
	}},
}

// Templates returns a copy of the supported creation presets.
func Templates() []Template {
	result := make([]Template, len(templateCatalog))
	copy(result, templateCatalog)
	for index := range result {
		result[index].Projects = append([]TemplateProject(nil), result[index].Projects...)
	}
	return result
}

// FindTemplate resolves a catalog identifier.
func FindTemplate(id string) (Template, bool) {
	for _, template := range templateCatalog {
		if template.ID == strings.TrimSpace(strings.ToLower(id)) {
			return template, true
		}
	}
	return Template{}, false
}

// PlanCreate validates a creation request without touching the filesystem.
func PlanCreate(request CreateRequest) (CreatePlan, error) {
	template, ok := FindTemplate(request.TemplateID)
	if !ok {
		return CreatePlan{}, fmt.Errorf("unknown project template %q", request.TemplateID)
	}
	name := strings.TrimSpace(request.Name)
	if !validTemplateName.MatchString(name) {
		return CreatePlan{}, fmt.Errorf("project name %q must contain only letters, numbers, '.', '_' or '-'", name)
	}
	destination := strings.TrimSpace(request.Destination)
	if destination == "" || !filepath.IsAbs(destination) {
		return CreatePlan{}, fmt.Errorf("destination must be an absolute path")
	}
	destination = filepath.Clean(destination)
	if request.ExistingSolution != "" && request.CreateSolution {
		return CreatePlan{}, fmt.Errorf("choose an existing solution or create a new solution, not both")
	}

	plan := CreatePlan{Template: template, Root: destination}
	projectPaths := make([]string, 0, len(template.Projects))
	for _, definition := range template.Projects {
		projectName := name
		if definition.Name != "" {
			projectName += definition.Name
		}
		folder := destination
		if definition.Folder != "" {
			folder = filepath.Join(folder, definition.Folder)
		}
		projectPath := filepath.Join(folder, projectName)
		projectPaths = append(projectPaths, projectPath)
		plan.Steps = append(plan.Steps, CreateStep{
			Dir:     destination,
			Command: []string{"dotnet", "new", definition.Kind, "--name", projectName, "--output", projectPath},
		})
	}
	plan.Projects = projectPaths

	if request.ExistingSolution != "" {
		if !filepath.IsAbs(request.ExistingSolution) {
			return CreatePlan{}, fmt.Errorf("existing solution must be an absolute path")
		}
		plan.Solution = filepath.Clean(request.ExistingSolution)
	} else if request.CreateSolution {
		plan.Solution = filepath.Join(destination, name+".sln")
		plan.Steps = append([]CreateStep{{
			Dir:     destination,
			Command: []string{"dotnet", "new", "sln", "--name", name, "--output", destination},
		}}, plan.Steps...)
	}
	if plan.Solution != "" {
		for _, projectPath := range projectPaths {
			plan.Steps = append(plan.Steps, CreateStep{
				Dir:     destination,
				Command: []string{"dotnet", "sln", plan.Solution, "add", projectPath},
			})
		}
	}
	return plan, nil
}
